const CODE_DIJ = `#include <algorithm>
#include <cstdio>
#include <functional>
#include <limits>
#include <queue>
#include <string>
#include <utility>
#include <vector>

struct Edge { int to; long long w; };
using Graph = std::vector<std::vector<Edge>>;
constexpr long long INF = std::numeric_limits<long long>::max();

struct Result {
    std::vector<long long> dist;
    std::vector<int> parent;
    int pushes = 0, pops = 0, stale = 0;
};

Result dijkstra(const Graph& g, int s) {
    Result r;
    r.dist.assign(g.size(), INF);
    r.parent.assign(g.size(), -1);
    using Item = std::pair<long long, int>;  // (tentative distance, vertex)
    std::priority_queue<Item, std::vector<Item>, std::greater<>> pq;  // min-heap
    r.dist[s] = 0;
    pq.push({0, s});
    ++r.pushes;
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        ++r.pops;
        if (d > r.dist[u]) { ++r.stale; continue; }  // lazy deletion
        for (auto [v, w] : g[u]) {
            if (r.dist[u] + w < r.dist[v]) {  // relax (u, v)
                r.dist[v] = r.dist[u] + w;
                r.parent[v] = u;
                pq.push({r.dist[v], v});
                ++r.pushes;
            }
        }
    }
    return r;
}

std::vector<int> pathTo(const std::vector<int>& parent, int t) {
    std::vector<int> path;
    for (int v = t; v != -1; v = parent[v]) path.push_back(v);
    std::reverse(path.begin(), path.end());  // we walked it backwards
    return path;
}

int main() {
    const std::string name = "SABCDT";
    Graph g(6);
    auto add = [&](int u, int v, long long w) {  // undirected edge
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    };
    add(0, 1, 6); add(0, 2, 2); add(2, 1, 3); add(1, 3, 2);  // S-A S-B B-A A-C
    add(2, 4, 8); add(3, 4, 2); add(3, 5, 7); add(4, 5, 2);  // B-D C-D C-T D-T

    Result r = dijkstra(g, 0);
    for (int v = 0; v < 6; ++v) std::printf("dist(%c) = %lld\\n", name[v], r.dist[v]);
    std::printf("path to T:");
    for (int v : pathTo(r.parent, 5)) std::printf(" %c", name[v]);
    std::printf("\\npushes %d, pops %d, stale pops %d\\n", r.pushes, r.pops, r.stale);
}`;
