const CODE_COUNTS = `#include <algorithm>
#include <cstdio>
#include <functional>
#include <limits>
#include <queue>
#include <random>
#include <utility>
#include <vector>

struct Edge { int to, w; };
using Graph = std::vector<std::vector<Edge>>;
constexpr int INF = std::numeric_limits<int>::max();

Graph randomGraph(int n, long long m, std::mt19937& rng) {
    Graph g(n);
    for (int v = 1; v < n; ++v)  // a random tree first, so everything is reachable
        g[rng() % v].push_back({v, int(1 + rng() % 100)});
    for (long long k = n - 1; k < m; ++k)
        g[rng() % n].push_back({int(rng() % n), int(1 + rng() % 100)});
    return g;
}

// Lazy binary-heap Dijkstra: count heap operations.
void heapVersion(const Graph& g, long long& pushes, long long& stale, size_t& maxHeap) {
    std::vector<int> dist(g.size(), INF);
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<>> pq;
    dist[0] = 0;
    pq.push({0, 0});
    pushes = 1, stale = 0, maxHeap = 1;
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) { ++stale; continue; }
        for (auto [v, w] : g[u])
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
                ++pushes;
                maxHeap = std::max(maxHeap, pq.size());
            }
    }
}

// Array Dijkstra: each round scans all vertices for the smallest unsettled one.
long long arrayVersion(const Graph& g) {
    const int n = int(g.size());
    std::vector<int> dist(n, INF);
    std::vector<bool> done(n, false);
    dist[0] = 0;
    long long scans = 0;
    for (int round = 0; round < n; ++round) {
        int u = -1;
        for (int v = 0; v < n; ++v, ++scans)
            if (!done[v] && (u == -1 || dist[v] < dist[u])) u = v;
        if (dist[u] == INF) break;
        done[u] = true;
        for (auto [v, w] : g[u])
            if (dist[u] + w < dist[v]) dist[v] = dist[u] + w;
    }
    return scans;
}

int main() {
    std::mt19937 rng(2026);
    const int n = 2000;
    for (long long m : {10LL * n, 1LL * n * n / 2}) {
        Graph g = randomGraph(n, m, rng);
        long long pushes, stale;
        size_t maxHeap;
        heapVersion(g, pushes, stale, maxHeap);
        std::printf("V = %d, E = %lld\\n", n, m);
        std::printf("  heap:  %lld pushes, %lld stale pops, max heap size %zu\\n", pushes, stale, maxHeap);
        std::printf("  array: %lld vertex scans\\n", arrayVersion(g));
    }
}`;
