const CODE_01 = `#include <cstdio>
#include <deque>
#include <string>
#include <vector>

// Fewest walls to breach: stepping onto '.' costs 0, onto '#' costs 1.
int main() {
    std::vector<std::string> grid = {
        "S..........",
        ".#########.",
        ".#.......#.",
        ".#.#####.#.",
        ".#.#.G.#.#.",
        ".#.#####.#.",
        ".#.......#.",
        ".#########.",
    };
    const int R = int(grid.size()), C = int(grid[0].size());
    const int INF = 1 << 29;
    std::vector<int> dist(R * C, INF), parent(R * C, -1);
    std::deque<int> dq;
    dist[0] = 0;  // S is at (0, 0)
    dq.push_back(0);
    int popped = 0;
    while (!dq.empty()) {
        int cell = dq.front();
        dq.pop_front();
        ++popped;
        int r = cell / C, c = cell % C;
        const int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
            int next = nr * C + nc;
            int w = grid[nr][nc] == '#' ? 1 : 0;
            if (dist[cell] + w < dist[next]) {
                dist[next] = dist[cell] + w;
                parent[next] = cell;
                if (w == 0) dq.push_front(next);  // same distance: front
                else dq.push_back(next);          // one more: back
            }
        }
    }
    int goal = 4 * C + 5;
    std::printf("walls to breach: %d\\n", dist[goal]);
    for (int v = parent[goal]; v != 0; v = parent[v])
        grid[v / C][v % C] = grid[v / C][v % C] == '#' ? 'X' : '*';
    for (const auto& row : grid) std::printf("%s\\n", row.c_str());
    std::printf("deque pops: %d (cells: %d)\\n", popped, R * C);
}`;
